class Solution:

	def minStepToReachTarget(self, KnightPos, TargetPos, N):
		vis = [[-1] * (N + 1) for i in range(N + 1)]
		if KnightPos == TargetPos:
			return 0
		q = [(KnightPos[0], KnightPos[1], 0)]
		vis[KnightPos[0]][KnightPos[1]] = 0
		d = [[2, 1], [2, -1], [-2, 1], [-2, -1], [1, 2], [1, -2], [-1, -2], [-1, 2]]
		while q:
			(x, y, step) = q.pop(0)
			for (i, j) in d:
				r = x + i
				c = y + j
				if [r, c] == TargetPos:
					return step + 1
				if 0 <= r <= N and 0 <= c <= N and (vis[r][c] == -1):
					q.append([r, c, step + 1])
					vis[r][c] = step + 1
		return -1
